Declare
  nStr     NUMERIC;
Begin
  Select Stor_Id
    Into nStr
    From Str_InMst
    Where Id=NEW.Mst_Id;
  NEW.Cst := COALESCE(NEW.Amt,0);
  Update Str_SMat Set
         CQnt=COALESCE(CQnt,0)+COALESCE(NEW.Qnt,0),
