CREATE OR REPLACE FUNCTION Str_TBI_OuTrn_fn() RETURNS TRIGGER AS $$
Declare
  nStr    NUMERIC;
  nCst    NUMERIC;
  nQnt    NUMERIC;
Begin
  Select Stor_Id
    Into nStr
    From Str_OuMst
    Where Id=NEW.Mst_Id;
  nQnt := 0;
  nCst := 0;
  Select COALESCE(CQnt,0), COALESCE(CAmt,0)
    Into nQnt, nCst
    From Str_SMat
   Where Stor_Id=nStr
     And Item_Id=NEW.Item_Id;
  -- Avrage
  If nQnt>0 Then
    nCst := nCst / nQnt;
