         CQnt=COALESCE(CQnt,0)-COALESCE(NEW.Qnt,0),
         CAmt=COALESCE(CAmt,0)-COALESCE(NEW.Cst,0)
   Where Stor_Id=nStr
     And Item_Id=NEW.Item_Id;
Exception
  When No_Data_Found Then
    RAISE EXCEPTION '%', 'Undefined Item '||NEW.Item_Id||' In Store '||nStr;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

